<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class AuthApiController extends Controller{public function register(Request $r){$d=$r->validate(['name'=>'required|max:100','email'=>'required|email|unique:users,email','password'=>'required|min:8|confirmed']);$u=User::create($d+['role'=>'customer']);return response()->json(['token'=>$u->createToken('mobile')->plainTextToken,'user'=>$u],201);}public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']);$u=User::where('email',$d['email'])->where('is_active',true)->first();if(!$u||!Hash::check($d['password'],$u->password))return response()->json(['message'=>'Invalid credentials'],422);return response()->json(['token'=>$u->createToken('mobile')->plainTextToken,'user'=>$u]);}public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Logged out']);}}
